class Solution:
    def numberOfSubsequences(self, nums: List[int]) -> int:
        from math import gcd
        from collections import defaultdict
        n = len(nums)
        ans = 0
        L = defaultdict(int)
        for r in range(n):
            if r >= 2:
                q = r - 2
                x = nums[q]
                for p in range(q - 1):
                    y = nums[p]
                    g = gcd(x, y)
                    L[(y // g, x // g)] += 1
            if r + 2 < n:
                xr = nums[r]
                R = defaultdict(int)
                for s in range(r + 2, n):
                    y = nums[s]
                    g = gcd(y, xr)
                    R[(y // g, xr // g)] += 1
                for k, c in R.items():
                    ans += c * L.get(k, 0)
        return ans

