class Solution {
    pair<int,int> key(int a, int b) {
        int g = __gcd(a, b);
        return {a / g, b / g};
    }
public:
    int numberOfSubsequences(vector<int>& nums) {
        int n = nums.size();
        long long ans = 0;
        map<pair<int,int>, long long> L;
        for (int r = 0; r < n; r++) {
            if (r >= 2) {
                int q = r - 2, x = nums[q];
                for (int p = 0; p <= q - 2; p++)
                    L[key(nums[p], x)]++;
            }
            if (r + 2 < n) {
                int xr = nums[r];
                map<pair<int,int>, long long> R;
                for (int s = r + 2; s < n; s++)
                    R[key(nums[s], xr)]++;
                for (auto& kv : R) {
                    auto it = L.find(kv.first);
                    if (it != L.end()) ans += kv.second * it->second;
                }
            }
        }
        return (int)ans;
    }
};

