class Solution {
    private long key(int a, int b) {
        int g = gcd(a, b);
        return (long)(a / g) * 1001 + (b / g);
    }
    private int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
    public int numberOfSubsequences(int[] nums) {
        int n = nums.length;
        long ans = 0;
        Map<Long, Long> L = new HashMap<>();
        for (int r = 0; r < n; r++) {
            if (r >= 2) {
                int q = r - 2, x = nums[q];
                for (int p = 0; p <= q - 2; p++)
                    L.merge(key(nums[p], x), 1L, Long::sum);
            }
            if (r + 2 < n) {
                int xr = nums[r];
                Map<Long, Long> R = new HashMap<>();
                for (int s = r + 2; s < n; s++)
                    R.merge(key(nums[s], xr), 1L, Long::sum);
                for (Map.Entry<Long, Long> e : R.entrySet()) {
                    Long c = L.get(e.getKey());
                    if (c != null) ans += c * e.getValue();
                }
            }
        }
        return (int)ans;
    }
}

