var numberOfSubsequences = function(nums) {
    const n = nums.length;
    let ans = 0;
    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);
    const L = new Map();
    for (let r = 0; r < n; r++) {
        if (r >= 2) {
            const q = r - 2, x = nums[q];
            for (let p = 0; p <= q - 2; p++) {
                const y = nums[p], g = gcd(x, y);
                const k = (y / g) * 1001 + x / g;
                L.set(k, (L.get(k) || 0) + 1);
            }
        }
        if (r + 2 < n) {
            const xr = nums[r], R = new Map();
            for (let s = r + 2; s < n; s++) {
                const y = nums[s], g = gcd(y, xr);
                const k = (y / g) * 1001 + xr / g;
                R.set(k, (R.get(k) || 0) + 1);
            }
            for (const [k, c] of R) ans += c * (L.get(k) || 0);
        }
    }
    return ans;
};
